      'support.nav.troubleshooting': 'Solução de problemas',
      'support.nav.accessibility': 'Permissão de Acessibilidade',
      'support.nav.notExpanding': 'Trechos que não se expandem',
      'support.nav.faq': 'Perguntas frequentes',
